import { afterEach, describe, expect, test } from "bun:test";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { tmpdir } from "node:os";

const cli = join(import.meta.dir, "..", "src", "cli.ts");
const directories: string[] = [];

async function workspace(): Promise<{ directory: string; database: string }> {
  const directory = await mkdtemp(join(tmpdir(), "taskboard-test-"));
  directories.push(directory);
  return { directory, database: join(directory, "tasks.json") };
}

async function invoke(database: string, args: string[]) {
  const process = Bun.spawn(["bun", "run", cli, ...args], {
    env: { ...Bun.env, TASKBOARD_FILE: database },
    stdout: "pipe",
    stderr: "pipe",
  });
  const [stdout, stderr, exitCode] = await Promise.all([
    new Response(process.stdout).text(),
    new Response(process.stderr).text(),
    process.exited,
  ]);
  const lines = stdout.trim().split("\n");
  expect(lines).toHaveLength(1);
  return { value: JSON.parse(lines[0]), stderr, exitCode };
}

afterEach(async () => {
  await Promise.all(directories.splice(0).map((directory) => rm(directory, { recursive: true, force: true })));
});

describe("taskboard CLI", () => {
  test("persists tasks across processes and keeps IDs stable after deletion", async () => {
    const { database } = await workspace();
    const first = await invoke(database, ["add", "--title", " First ", "--tags", "Work, work, HOME", "--due", "2099-01-01"]);
    expect(first.exitCode).toBe(0);
    expect(first.value).toMatchObject({ id: 1, title: "First", status: "open", tags: ["work", "home"], due: "2099-01-01" });

    expect((await invoke(database, ["delete", "1"])).exitCode).toBe(0);
    const second = await invoke(database, ["add", "--title", "Second"]);
    expect(second.value.id).toBe(2);
    expect((await invoke(database, ["list"])).value.map((task: { id: number }) => task.id)).toEqual([2]);
  });

  test("combines filters and applies strict overdue semantics", async () => {
    const { database } = await workspace();
    await invoke(database, ["add", "--title", "old", "--tags", "Ops", "--due", "2020-01-01"]);
    await invoke(database, ["add", "--title", "boundary", "--tags", "ops", "--due", "2020-01-02"]);
    await invoke(database, ["add", "--title", "other", "--tags", "dev", "--due", "2019-01-01"]);
    await invoke(database, ["done", "1"]);

    const result = await invoke(database, ["list", "--status", "open", "--tag", "OPS", "--overdue", "2020-01-03"]);
    expect(result.value.map((task: { id: number }) => task.id)).toEqual([2]);
    expect((await invoke(database, ["list", "--overdue", "2020-01-02"])).value.map((task: { id: number }) => task.id)).toEqual([3]);
  });

  test("done is idempotent and stats count only open overdue tasks", async () => {
    const { database } = await workspace();
    await invoke(database, ["add", "--title", "late", "--due", "2000-01-01"]);
    await invoke(database, ["add", "--title", "also late", "--due", "2000-01-01"]);
    const done = await invoke(database, ["done", "1"]);
    const repeated = await invoke(database, ["done", "1"]);
    expect(repeated.value.completedAt).toBe(done.value.completedAt);
    expect(await invoke(database, ["stats"])).toMatchObject({ value: { total: 2, open: 1, done: 1, overdue: 1 }, exitCode: 0 });
  });

  test("rejects invalid input with one JSON stdout value", async () => {
    const { database } = await workspace();
    for (const args of [
      ["add", "--title", "   "],
      ["add", "--title", "bad date", "--due", "2023-02-29"],
      ["list", "--wat", "x"],
      ["done", "99"],
      ["mystery"],
    ]) {
      const result = await invoke(database, args);
      expect(result.exitCode).not.toBe(0);
      expect(result.value.error).toBeString();
      expect(result.stderr.trim()).not.toBe("");
    }
  });

  test("does not replace a malformed database", async () => {
    const { database } = await workspace();
    const malformed = "{ definitely not json";
